{
  "title": "Context Engineering: Sessions, Memory",
  "summary": "构建有状态、智能化 LLM Agent 的关键在于 Context Engineering，涉及 Sessions 和 Memory 的有效管理。",
  "core_concepts": [
    {
      "name": "Context Engineering",
      "definition": "Context Engineering 是动态组装和管理 LLM 上下文窗口内信息，以实现有状态、智能化 Agent 的过程。它涉及策略性地选择、总结和注入不同类型的信息，以最大化相关性并最小化噪音。",
      "key_points": [
        "是 Prompt Engineering 的演进，关注整个 payload 而非仅 system instructions",
        "目标是构建针对特定任务的最佳上下文",
        "涉及多个组件，例如 System Instructions、Tool Definitions、Few-Shot Examples、Evidential & Factual Data、Long-Term Memory、External Knowledge等"
      ]
    },
    {
      "name": "Sessions",
      "definition": "Session 是一个会话的容器，包含与 Agent 完整对话的 chronological history 以及 Agent 的 working memory (state)。它是一个自包含的记录，与特定用户绑定，允许 Agent 维护上下文并在会话范围内提供连贯的响应。",
      "key_points": [
        "包含 events (对话 building blocks) 和 state (working memory)",
        "不同的 Agent Framework 以不同的方式实现 Sessions、Events 和 State",
        "生产环境需要考虑 security and privacy、data integrity 和 performance"
      ]
    },
    {
      "name": "Memory",
      "definition": "Memory 是长期持久化机制，用于捕获和整合跨多个 Session 的关键信息，为 LLM Agent 提供连续和个性化的体验。它是从对话或数据源中提取的、有意义信息的快照，保存重要的上下文，使其对未来的交互有用。",
      "key_points": [
        "与 Sessions 共享共生关系：Sessions 是生成 Memory 的主要数据源",
        "用于实现 personalization、context window management、data mining and insight 和 agent self-improvement and adaptation",
        "涉及 Extraction、Consolidation、Storage 和 Retrieval 过程",
        "需要考虑 types of memory, organization patterns, storage architectures, creation mechanisms, memory scope 和 multimodal memory",
        "需要考虑 memory provenance，确保 trustworthiness"
      ]
    },
    {
      "name": "Memory Generation",
      "definition": "Memory generation 是一个 LLM 驱动的 ETL (Extract, Transform, Load) pipeline，旨在从原始对话数据中提取和压缩记忆。 它涉及数据提取、过滤和整合，以创建结构化且有意义的 insights。",
      "key_points": [
        "分为 Ingestion, Extraction & Filtering, Consolidation, Storage 四个阶段",
        "Extraction 目标是确定哪些信息足够重要以成为记忆",
        "Consolidation 解决信息重复、信息冲突、信息演变等问题",
        "触发方式可以基于 Count-Based Triggers、Time-Based Triggers 和 Event-Based Triggers"
      ]
    },
    {
      "name": "Memory Retrieval",
      "definition": "Memory Retrieval 是搜索和选择与当前对话最相关的记忆的关键过程。 智能检索策略对于 Agent 的性能至关重要，需要仔细考虑应检索哪些记忆以及何时检索。",
      "key_points": [
        "评估指标包括 Relevance (Semantic Similarity)、Recency (Time-based) 和 Importance (Significance)",
        "可以通过 query rewriting, reranking 或 specialized retrievers 来优化检索",
        "时间选择上可以是 proactive retrieval 或 reactive retrieval (“Memory-as-a-Tool”)"
      ]
    },
        {
      "name": "Memory Provenance",
      "definition": "Memory Provenance 是一个 Memory 的详细记录，包括其来源和历史。Provenance 对于评估 Memory 的质量至关重要，并且可以帮助 Agent 在推理过程中做出可靠的决定。",
      "key_points": [
        "用于确定 data source 的 trust，例如 Bootstrapped Data、User Input、Tool Output",
        "Provenance 允许 memory manager 建立 information sources 的信任等级",
        "记忆的 confidence 必须不断演变，并被纳入到推理过程中"
      ]
    }
  ],
  "best_practices": [
    {
      "practice": "PII Redaction",
      "description": "在将 Session 数据写入存储之前，编辑个人身份信息 (PII) 是一个最佳实践，可以显著降低数据泄露的风险。可以使用 Model Armor 等工具。",
      "example": "使用 Model Armor 工具，在将任何 Session 数据保存到持久存储之前，自动检测和删除 PII。"
    },
    {
      "practice": "Asynchronous Memory Generation",
      "description": "为了避免阻塞用户体验，Memory Generation 应该以 asynchronous background process 的方式处理。",
      "example": "Agent 将原始会话数据推送到 Memory Manager，Memory Manager 在后台处理数据并更新 Memory，而不会影响 Agent 的响应时间。"
    },
    {
      "practice": "Compacting Long Context Conversations",
      "description": "使用 summarization、selective pruning 或其他 compaction techniques，动态地改变会话历史，以保存重要信息，同时管理总 token 数量。",
      "example": "在对话超过一定数量的 token 时，使用 LLM 自动总结较早的对话内容，并将其替换为摘要。"
    }
  ],
  "architecture_patterns": [
    {
      "pattern": "Shared, Unified History (Multi-Agent Systems)",
      "description": "所有 Agent 都从同一个单一会话历史记录中读取和写入事件。每个 Agent 的消息、工具调用和观察结果都按时间顺序附加到一个中心日志中。",
      "use_case": "适用于紧密耦合的协作任务，需要单一 truth 来源，例如多步骤问题解决过程，其中一个 Agent 的输出是下一个 Agent 的直接输入。"
    },
    {
      "pattern": "Separate, Individual Histories (Multi-Agent Systems)",
      "description": "每个 Agent 维护自己的私有会话历史记录，其他 Agent 将其视为黑盒。所有内部流程（例如中间想法、工具使用和推理步骤）都保留在 Agent 的私有日志中，对其他人不可见。",
      "use_case": "适用于 Agent 间只通过明确消息通信的场景，其中 Agent 共享其最终输出，而不是其过程。"
    },
    {
      "pattern": "Internal Memory",
      "description": "将记忆管理直接构建到 Agent Framework 中。它方便入门，但通常缺乏高级功能。内部记忆可以使用外部存储，但生成记忆的机制是 Agent 内部的。",
      "use_case": "适用于快速原型设计或简单应用，对记忆管理功能要求不高。"
    },
    {
      "pattern": "External Memory",
      "description": "使用专门的外部服务进行记忆管理（例如 Agent Engine Memory Bank, Mem0, Zep）。Agent Framework 调用此外部服务来存储、检索和处理记忆。",
      "use_case": "适用于需要高级记忆管理功能的应用，例如语义搜索、实体提取和自动总结。"
    }
  ],
  "code_snippets": [
    {
      "description": "Example multi-turn call to Gemini",
      "language": "python",
      "code": "contents = [
{
"role": "user",
"parts": [ {"text": "What is the capital of France?"} ]
},
{
"role": "model",
"parts": [ {"text": "The capital of France is Paris."} ]
}
]
response = client.models.generate_content(
model="gemini-2.5-flash",
contents=contents
)"
    },
    {
      "description": "Session truncation to only use the last N turns with ADK",
      "language": "python",
      "code": "from google.adk.apps import App
from google.adk.plugins.context_filter_plugin import ContextFilterPlugin

app = App(
    name='hello_world_app',
    root_agent=agent,
    plugins=[
        # Keep the last 10 turns and the most recent user query.
        ContextFilterPlugin(num_invocations_to_keep=10),
    ],
)"
    },
    {
      "description": "Session compaction using summarization with ADK",
      "language": "python",
      "code": "from google.adk.apps import App
from google.adk.apps.app import EventsCompactionConfig

app = App(
    name='hello_world_app',
    root_agent=agent,
    events_compaction_config=EventsCompactionConfig(
        compaction_interval=5,
        overlap_size=1,
    ),
)"
    },
    {
      "description": "Example memory generation API call for Agent Engine Memory Bank",
      "language": "python",
      "code": "types.Part.from_bytes(
    data=CONTENT_AS_BYTES,
    mime_type=MIME_TYPE
),
types.Part.from_uri(
    file_uri="file/path/to/content",
