    },
    {
      "description": "Generate memories with Agent Engine Memory Bank",
      "language": "python",
      "code": "from google.cloud import vertexai
client = vertexai.Client(project=..., location=...)

client.agent_engines.memories.generate(
    name="projects/.../locations/...reasoningEngines/...",
    scope={"user_id": "123"},
